import type { ReactNode } from "react";

export const invoicesTableSelectionModeValues = ["none", "multiple"] as const;
export const invoicesTableDensityValues = ["compact", "standard", "comfortable"] as const;
export const invoicesTableLayoutValues = ["auto", "table", "cards"] as const;

/** The invoice list of a billing page or an accounts screen: number, customer, issue and due dates, amount and a status in words. Overdue is worked out from the due date. Search, filter by status, sort, pages, selection, CSV, and the invoice actions (download, remind, record payment, void) each behind a permission and a confirmation. Totals above show what is outstanding, overdue and paid. It never fetches, sends or charges: you pass the invoices and do the actions. */
export interface InvoicesTableSpecProps {
  /**
   * The invoices to show. With serverSide, only the current page.
   */
  invoices: import("../invoices-table/query").Invoice[];
  /**
   * Accessible name of the table and the section, e.g. "Invoices".
   * @default "Invoices"
   */
  label?: string;
  /**
   * ISO currency code of the table, e.g. "USD" or "EUR". An invoice can carry its own. The totals above the table add up this currency only and say how many invoices they left out.
   * @default "USD"
   */
  currency?: string;
  /**
   * Locale for numbers and dates, e.g. "en-GB". Defaults to en-US while rendering on the server and during hydration, then the visitor's language.
   */
  locale?: string;
  /**
   * The day that decides what is overdue and what counts as paid in the last 30 days, as an ISO day such as "2026-03-15". Defaults to today. Set it in tests, screenshots and server rendering so the page never changes underneath you.
   */
  asOf?: string;
  /**
   * The totals above the table. "auto" works them out from the invoices (not with serverSide, where the table sees one page only); "none" hides them; or pass your own numbers.
   * @default "auto"
   */
  summary?: "auto" | "none" | import("../invoices-table/query").InvoiceSummary;
  /**
   * The data state, when your data layer gives you one: loading, empty, error or ready. It wins over isLoading and error. A ready table with no matching rows says nothing matches.
   */
  state?: import("../utils/state").DataState;
  /**
   * Show loading rows and skeleton cards, disable the controls, and mark the section busy.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Something went wrong loading: a message to show instead of the rows (true uses a general one).
   */
  error?: string | boolean;
  /**
   * Adds a Try again button to the error state.
   */
  onRetry?: () => void;
  /**
   * Title shown when there are no rows at all. Defaults to "Nothing here yet".
   */
  emptyTitle?: string;
  /**
   * Text under the empty title.
   */
  emptyDescription?: string;
  /**
   * A control shown in the empty state when there are no rows at all (not when a search found nothing), such as an Add button.
   */
  emptyAction?: import("react").ReactNode;
  /**
   * Rows per page.
   * @default 10
   */
  pageSize?: number;
  /**
   * The search, filters, sort and page, when you keep them yourself (for example in the address). Without it the table keeps them.
   */
  query?: import("../data-table/query").DataTableQuery;
  /**
   * Start with a search, filters, a sort or a page already set.
   */
  defaultQuery?: Partial<import("../data-table/query").DataTableQuery>;
  /**
   * Called with the new query whenever the search, a filter, the sort or the page changes (typing waits for a short pause with serverSide). With serverSide, answer it with new rows.
   */
  onQueryChange?: (query: import("../data-table/query").DataTableQuery) => void;
  /**
   * Called with the search text whenever it changes.
   */
  onSearch?: (search: string) => void;
  /**
   * Called with the chosen values of every filter whenever a filter changes or the filters are cleared.
   */
  onFilter?: (filters: Record<string, string[]>) => void;
  /**
   * The rows live on a server. The table then shows exactly the rows you pass and asks for new ones through onQueryChange.
   * @default false
   */
  serverSide?: boolean;
  /**
   * With serverSide: how many rows match in all, so the pages and the count are right.
   */
  totalCount?: number;
  /**
   * Add checkboxes to pick rows. The header box selects the rows on the page.
   * @default "none"
   */
  selectionMode?: "none" | "multiple";
  /**
   * Controlled selection: the ids of the selected rows.
   */
  selectedKeys?: Set<string>;
  /**
   * Rows selected at the start.
   */
  defaultSelectedKeys?: Iterable<string>;
  /**
   * Called with the ids of the selected rows.
   */
  onSelectionChange?: (keys: Set<string>) => void;
  /**
   * Replaces the built-in CSV download. It gets the rows that match (all pages when the list is in memory) and the query. With serverSide the Export button is shown only when you give this.
   */
  onExport?: (rows: any[], query: import("../data-table/query").DataTableQuery) => void;
  /**
   * Row spacing of the table.
   * @default "standard"
   */
  density?: "compact" | "standard" | "comfortable";
  /**
   * Table or cards. auto shows cards when the block itself is narrower than about 640px (not just the screen).
   * @default "auto"
   */
  layout?: "auto" | "table" | "cards";
  /**
   * What the app allows, by action: open, download, remind (send a reminder), markPaid, void, export (Export CSV) and select (the checkboxes). Each answer is "allow", "disabled", "hidden", true, false or { state, reason }. Hidden removes the action; disabled keeps it visible with the reason. Actions that do not fit an invoice (a reminder for a paid one) never show, whatever the answer. The server must check every action again: the page is not security.
   */
  permissions?: import("../utils/permissions").Permissions<"open" | "download" | "remind" | "markPaid" | "void" | "export" | "select">;
  /**
   * Makes each invoice number a button and calls this with the invoice, e.g. to open a details page or panel.
   */
  onOpenInvoice?: (invoice: import("../invoices-table/query").Invoice) => void;
  /**
   * Adds Download PDF to each row, and to the bulk bar for the selected rows. Called with the invoices to download. You make the file.
   */
  onDownload?: (invoices: import("../invoices-table/query").Invoice[]) => void | Promise<unknown>;
  /**
   * Adds Send reminder to unpaid rows (after a confirmation) and to the bulk bar for the selected unpaid ones. Called with the invoices to remind. You send the email.
   */
  onSendReminder?: (invoices: import("../invoices-table/query").Invoice[]) => void | Promise<unknown>;
  /**
   * Adds Record payment to unpaid rows, after a confirmation. Called with the invoice. You record the payment.
   */
  onMarkPaid?: (invoice: import("../invoices-table/query").Invoice) => void | Promise<unknown>;
  /**
   * Adds Void invoice to rows that can still be voided, after a confirmation. Called with the invoice. Voiding is yours to do and to allow.
   */
  onVoid?: (invoice: import("../invoices-table/query").Invoice) => void | Promise<unknown>;
  /**
   * Which badge color a status gets. The defaults are draft neutral, open blue, overdue amber, paid green, void neutral.
   */
  statusTones?: Partial<Record<import("../invoices-table/query").InvoiceStatus, "neutral" | "info" | "success" | "warning" | "danger">>;
  /**
   * Class names for the parts of the block, by slot name, added after the built-in ones so you can restyle one part without editing the file. Slots: root, summary, stat, toolbar, search, filters, count, export, bulk-bar, table, header, row, cell, cards, card, empty, error, footer, pagination.
   */
  classNames?: Partial<Record<"root" | "summary" | "stat" | "toolbar" | "search" | "filters" | "count" | "export" | "bulk-bar" | "table" | "header" | "row" | "cell" | "cards" | "card" | "empty" | "error" | "footer" | "pagination", string>>;
}

export const invoicesTableDefaults = {
  label: "Invoices",
  currency: "USD",
  summary: "auto",
  isLoading: false,
  pageSize: 10,
  serverSide: false,
  selectionMode: "none",
  density: "standard",
  layout: "auto",
} as const;

export const invoicesTableMeta = {
  "name": "InvoicesTable",
  "version": "0.1.0",
  "status": "experimental",
  "role": "region"
} as const;
